import{c as n,Q as a,j as r,m as s}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"The Interplay of Harness Design and Post-Training in LLM Agents","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.25447","title":"The Interplay of Harness Design and Post-Training in LLM Agents","archived_date":"2026-07-18T00:00:00.000Z","arxiv_id":2606.25447,"authors":["Kyungmin Kim","Youngbin Choi","Seoyeon Lee","Suhyeon Jun","Dongwoo Kim","Sangdon Park"],"pdf_path":"pdfs/2606.25447.pdf","published_date":"2026-06-24T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-24-interplay-harness-design-post-training-2606-25447.md","filePath":"research/papers/2026-06-24-interplay-harness-design-post-training-2606-25447.md","lastUpdated":1785909234000}'),t={name:"research/papers/2026-06-24-interplay-harness-design-post-training-2606-25447.md"};function i(o,e,h,g,d,l){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="the-interplay-of-harness-design-and-post-training-in-llm-agents" tabindex="-1">The Interplay of Harness Design and Post-Training in LLM Agents <a class="header-anchor" href="#the-interplay-of-harness-design-and-post-training-in-llm-agents" aria-label="Permalink to &quot;The Interplay of Harness Design and Post-Training in LLM Agents&quot;">​</a></h1><p><strong>Authors</strong>: Kyungmin Kim, Youngbin Choi, Seoyeon Lee, Suhyeon Jun, Dongwoo Kim, Sangdon Park <strong>Published</strong>: June 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.25447" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.25447</a><strong>arXiv ID</strong>: 2606.25447 <strong>Categories</strong>: Machine Learning (cs.LG); Computation and Language (cs.CL) <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.25447" target="_blank" rel="noreferrer">research/papers/pdfs/2606.25447.pdf</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>Tool-integrated LLM agents operate within scaffolding that determines which tools are exposed, how they are described, and what auxiliary information accompanies each per-step observation. The researchers examine how harness design influences post-training performance. They extend the ALFWorld benchmark to treat harness design as a controllable dimension and evaluate performance under task and tool environment shifts. Their findings demonstrate that harness-aware post-training not only improves in-distribution performance but also enables agents to robustly adapt to OOD settings. The work reveals significant performance degradation when using minimally-engineered harnesses under substantial tool environment shifts, emphasizing the necessity of considering harness design during agent post-training processes.</p><hr><h2 id="core-thesis" tabindex="-1">Core Thesis <a class="header-anchor" href="#core-thesis" aria-label="Permalink to &quot;Core Thesis&quot;">​</a></h2><ul><li>把「harness 設計」當作可控變因（哪些工具暴露、描述方式、每步觀察附帶的輔助資訊），並延伸 ALFWorld benchmark 系統性測試其對 post-training 效果的影響。</li><li>發現 harness-aware post-training 不只改善 in-distribution 表現，也讓 agent 在工具環境分佈偏移（OOD）下更穩健；反之，minimal-engineered harness 在工具環境大幅變動時效能顯著下降。</li><li>隱含結論：模型能力與 harness 設計是<strong>共同演化</strong>變因，訓練階段忽略 harness 設計會低估／高估真實泛化能力。</li><li><strong>Workspace 關聯</strong>：呼應本庫既有 Harness Engineering 主題（如 HarnessX、Scaling-Harness）——harness 不是訓練後的外掛，而是與模型能力共同決定泛化上限的一階設計變數；對 <code>model-profiles.md</code> 換模型世代時「規則需重審」的立場提供額外實證支持。</li></ul>',8)])])}const m=n(t,[["render",i]]);export{c as __pageData,m as default};
